'use strict';
const COMPETITION_UI6={bind,rivalsView,businessView,rivalDetail5,storesView,help};
function competitionClientsHTML6(){return `<h3>Souboj o odběratele</h3><p class="sub">Aktivní smlouvy se dodržují. V posledním týdnu soupeřova odběru můžeš připravit nabídku; podepsat ji lze po skončení. Kvalita a cena ovlivní podmínky, včasná obnova chrání tvé odběratele.</p><div class="table-scroll"><table class="data"><thead><tr><th>Klient</th><th>Dodavatel</th><th>Odběr</th><th>Konec</th><th></th></tr></thead><tbody>${state.competition6.clients.map(c=>{const player=state.contracts.find(x=>x.business5?.client===c.id),active=competitionActiveClient6(c),r=state.rivals.find(r=>r.id===c.rival);return `<tr><td>${esc(businessClient5(c.id).name)}<small>${esc(businessClient5(c.id).city)}</small></td><td>${player?'Tvoje firma':active?esc(r.name):'Otevřený trh'}</td><td>${player?player.kg+' kg · '+money(player.price)+'/kg':active?c.kg+' kg · '+money(c.price)+'/kg · kvalita '+c.quality:'—'}</td><td>${player?'Za '+player.remaining+' týdnů':active?'T'+c.until:'—'}</td><td><button class="soft" data-competition-client6="${c.id}">${player?'Spravovat smlouvu':'Připravit nabídku'}</button></td></tr>`}).join('')}</tbody></table></div>`;}
rivalsView=function(){const nearby=state.stores.flatMap(s=>competitionNeighbors6(s.id).map(n=>({store:s,...n})));return `<section class="card"><h2>Místní konkurenční tlak</h2>${nearby.length?nearby.map(n=>`<p><strong>${esc(loc(n.store.id).name)}</strong> · ${esc(state.rivals.find(r=>r.id===n.rival).name)} / ${esc(loc(n.id).name)}, ${money(n.price)}, kvalita ${n.quality}. <button class="quiet" data-competition-store6="${n.store.id}">Upravit nabídku ↗</button><button class="quiet" data-competition-city6="${loc(n.store.id).city}">Zvážit jinou adresu ↗</button></p>`).join(''):empty('V blízkosti tvých kaváren zatím nemá soupeř pobočku.')}<p class="sub">Blízkost vychází z herní mapy, ne ze skutečné vzdálenosti ulic. Cena a kvalita sousedních kaváren ovlivňují poptávku obou firem.</p></section><section class="card" style="margin-top:20px">${competitionClientsHTML6()}</section><div style="margin-top:24px">${COMPETITION_UI6.rivalsView()}</div>`;};
businessView=function(){return COMPETITION_UI6.businessView()+`<section class="card" style="margin-top:24px">${competitionClientsHTML6()}</section>`;};
rivalDetail5=function(id){COMPETITION_UI6.rivalDetail5(id);const r=state.rivals.find(r=>r.id===id);if(!r)return;const h=r.operations5.history.at(-1),node=document.createElement('section');node.innerHTML=`<h3>Úplné náklady a financování</h3>${h?.incomeTax!==undefined?rows([['Odvody a místní mzdy','Zahrnuté v nákladech kaváren'],['Daň z výsledku / vratka rezervy',money(h.incomeTax)],['Odpisy vybavení',money(h.depreciation)],['Splátka jistiny',money(h.principal)],['Úroky',money(h.interest)],['Placené vedení včetně odvodů',money(h.teamPay)],['Skutečný B2B odběr',h.clients.reduce((n,c)=>n+c.kg,0)+' kg'],['Dluh po týdnu',money(r.debt)]]):empty('Nový finanční model se projeví po uzavření týdne.')}<h3>Lidé ve vedení soupeře</h3>${r.competition6.team.map(p=>`<div class="card"><strong>${esc(p.name)}</strong><p>Dovednost ${p.skill}, mzda ${money(p.salary)}/týden, u soupeře ${p.tenure} týdnů. Dovednosti zlepšují kapacitu a práci se surovinami.</p>${state.stores.length?`<label>Cílová kavárna<select id="competitionTarget6-${esc(p.pid)}">${state.stores.map(s=>`<option value="${s.id}">${esc(loc(s.id).name)}</option>`).join('')}</select></label><button class="soft" data-competition-hire6="${esc(p.pid)}" data-rival="${r.id}" ${p.tenure<4?'disabled':''}>Připravit přestup zpět</button>`:''}</div>`).join('')||empty('Nemá převzatého vedoucího z tvé firmy.')}<h3>Konkrétní odběry posledního týdne</h3>${h?.clients?.map(c=>`<p>${esc(businessClient5(c.id).name)} · ${c.kg} kg · tržby ${money(c.revenue)}, náklady ${money(c.cost)}, přínos ${money(c.profit)}.</p>`).join('')||empty('Žádný sjednaný odběr.')}<p class="sub">Soupeř používá souhrnnou výrobu s omezenou kapacitou a placeným pražením. Jeho jednotlivé šarže a sklady nesimulujeme. Odhady investic jsou před daní, skutečný výsledek ji zahrnuje. Hotovost navíc ovlivní investice, nepeněžní odpisy a splátky jistiny.</p>`;el('modalContent').append(node);bindCompetition6();};
function bindCompetition6(){on('[data-competition-client6]',b=>{el('modal').close();goto('business');if(!businessAccount5(b.dataset.competitionClient6).contract)businessNegotiateDialog5(b.dataset.competitionClient6);});on('[data-competition-store6]',b=>{el('modal').close();menuStore=b.dataset.competitionStore6;goto('menu')});on('[data-competition-city6]',b=>{city=b.dataset.competitionCity6;goto('city')});on('[data-competition-hire6]',b=>act(()=>{const store=el('competitionTarget6-'+b.dataset.competitionHire6).value,q=competitionHireQuote6(b.dataset.rival,b.dataset.competitionHire6,store);show(`<span class="eyelabel">NABÍDKA PŘESTUPU</span><h2>${esc(q.person.name)}</h2><p>${esc(loc(store).name)} · bonus ${money(q.bonus)}, nábor ${money(q.fee)}, nová mzda ${money(q.salary)}/týden plus odvody. Stávající vedoucí této kavárny přejde do tvého seznamu talentů.</p><button class="primary" id="competitionConfirm6">Podepsat · ${money(q.bonus+q.fee)}</button><button class="soft" id="competitionCancel6">Zrušit</button>`);el('competitionConfirm6').onclick=()=>act(()=>{competitionHire6(q.rival,q.pid,q.store,q);el('modal').close();toast('Člověk přestoupil do tvé firmy.');render()});el('competitionCancel6').onclick=()=>el('modal').close();}));}
bind=function(){COMPETITION_UI6.bind();bindCompetition6();};
help=function(){COMPETITION_UI6.help();const p=document.createElement('p');p.textContent='Edice 05.17: soupeři platí místní mzdy, odvody, DPH, daň z výsledku, úroky a splátky. Rozhodují podle přínosu a rezervy. V konkurenci vidíš blízké pobočky a skutečné odběratele. Přetažený vedoucí má zachované jméno a dovednosti, soupeř mu platí mzdu; po čtyřech týdnech ho můžeš získat zpět.';el('modalContent').append(p);};el('help').onclick=help;render();
